import { WorldState, createInitialWorldState, applyOperation as applyWorldOperation } from "./world";

export interface WorldProtocol {
  reset(): WorldState;
  applyOperation(
    state: WorldState,
    operationDisplayName: string
  ): { success: true; newState: WorldState } | { success: false; error: string };
  getEntityState(state: WorldState, entityDisplayName: string): string;
  toAbstractSnapshot(state: WorldState): Record<string, string>;
}

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return createInitialWorldState();
  },

  applyOperation(state: WorldState, operationDisplayName: string) {
    return applyWorldOperation(state, operationDisplayName);
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    return state.entities[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return { ...state.entities };
  },
};

